 // QueenOS worker-starter: a dependency-free router. No build step: every
 // src/**/*.js file is uploaded as an ES module, so imports must be relative.
 import { features } from "./features/index.js";

 const json = (body, status = 200) =>
   new Response(JSON.stringify(body, null, 2) + "\n", {
     status,
     headers: { "content-type": "application/json; charset=utf-8" },
   });

+const html = (body, status = 200) =>
+  new Response(body, {
+    status,
+    headers: { "content-type": "text/html; charset=utf-8" },
+  });
+
+const statusPage = () => html(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>worker-starter status</title>
+  <style>
+    :root { color-scheme: light dark; }
+    body {
+      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+      line-height: 1.6;
+      max-width: 720px;
+      margin: 3rem auto;
+      padding: 0 1.5rem;
+      color: #222;
+      background: #fff;
+    }
+    h1 { font-size: 1.75rem; margin-bottom: 0.25rem; }
+    .badge {
+      display: inline-block;
+      padding: 0.2rem 0.6rem;
+      border-radius: 999px;
+      background: #22c55e;
+      color: #fff;
+      font-weight: 600;
+      font-size: 0.875rem;
+    }
+    ul { padding-left: 1.25rem; }
+    li { margin: 0.35rem 0; }
+    code {
+      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
+      background: #f3f4f6;
+      padding: 0.1rem 0.35rem;
+      border-radius: 0.25rem;
+    }
+    a { color: #2563eb; }
+    @media (prefers-color-scheme: dark) {
+      body { color: #e5e7eb; background: #111827; }
+      code { background: #1f2937; }
+      a { color: #60a5fa; }
+    }
+  </style>
+</head>
+<body>
+  <h1>worker-starter</h1>
+  <p><span class="badge">ok</span> This Cloudflare Worker is running.</p>
+  <h2>Features</h2>
+  <ul>
+    ${features.map((f) => `<li><a href="/features/${f.slug}"><code>${f.slug}</code></a></li>`).join("\n    ")}
+  </ul>
+  <p>Health check: <a href="/health"><code>/health</code></a></p>
+</body>
+</html>
+`);
+
 export default {
   async fetch(request) {
     const url = new URL(request.url);
     try {
       // Feature guards run on every request (auth, flags, rate limits, ...).
       for (const feature of features) {
         if (typeof feature.guard === "function") await feature.guard(request);
       }

       if (url.pathname === "/" || url.pathname === "") {
+        return statusPage();
-        return json({ ok: true, app: "worker-starter", features: features.map((f) => f.slug) });
       }
       if (url.pathname === "/health") return json({ ok: true });

       const match = /^\/features\/([a-z0-9-]+)\/?$/.exec(url.pathname);
       if (match) {
         const feature = features.find((f) => f.slug === match[1]);
         if (feature) return await feature.handle(request);
       }
       return json({ ok: false, error: "not found", path: url.pathname }, 404);
     } catch (err) {
       return json({ ok: false, error: String((err && err.message) || err) }, 500);
     }
   },
 };

